def shell(title,body):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'+E(title)+' | YUANWANG</title><meta name="description" content="Yuanwang geothermal, water engineering, spa products and project references."><link rel="icon" href="assets/yuanwang-logo-original.png"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="spa-theme.css"><link rel="stylesheet" href="business-hub.css"></head><body>'+nav+'<main class="hub-main">'+body+'</main>'+footer+'<script src="app.js" defer></script><script src="business-hub.js" defer></script></body></html>'
def hero(title,lead):return '<header class="hub-hero"><p class="overline">YUANWANG · WATER & WELLNESS</p><h1>'+E(title)+'</h1><p>'+E(lead)+'</p></header>'
def card(title,body,href,image=None):return '<article class="hub-card">'+(f'<img src="{image}" alt="{E(title)}" loading="lazy">' if image else '')+'<h2>'+E(title)+'</h2><p>'+E(body)+'</p><a class="hub-link" href="'+href+'">Explore →</a></article>'
def plate(im,title,body,out,num=''):
 width=1600;h=round(im.height/im.width*width);lines=textwrap.wrap(body,112,break_long_words=False,break_on_hyphens=False);height=116+h+145+32*len(lines)
 buf=io.BytesIO();im.convert('RGB').save(buf,'JPEG',quality=95,optimize=True);b=base64.b64encode(buf.getvalue()).decode()
 s=f'<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1600" height="{height}" viewBox="0 0 1600 {height}"><title>{E(title)}</title><desc>{E(body)}</desc><rect width="1600" height="{height}" fill="#f3f9f8"/><text x="48" y="46" font-family="Arial,sans-serif" font-size="18" fill="#397580">YUANWANG / ENGLISH READING EDITION {E(num)}</text><text x="48" y="88" font-family="Arial,sans-serif" font-size="30" fill="#173c49">{E(title)}</text><image x="0" y="116" width="1600" height="{h}" xlink:href="data:image/jpeg;base64,{b}"/><rect x="28" y="{h+140}" width="1544" height="{height-h-168}" rx="12" fill="white"/><text x="54" y="{h+180}" font-family="Arial,sans-serif" font-size="20" font-weight="bold" fill="#1a6979">ENGLISH TRANSLATION / DRAWING KEY</text>'
 for i,line in enumerate(lines):s+=f'<text x="54" y="{h+224+i*32}" font-family="Arial,Noto Sans CJK SC,sans-serif" font-size="24" fill="#234550">{E(line)}</text>'
 out.write_text(s+'</svg>')
